def fizzbuzz(n):
    '''Return a list of 1..n where multiples of 3 are 'Fizz', of 5 'Buzz', of both 'FizzBuzz'.'''
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(i)
    return result
```

