def two_sum(nums, target):
    '''Return indices (i, j), i < j, of the two numbers summing to target; nums always has exactly one solution.'''
    seen = {}
    for j, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return (seen[complement], j)
        seen[num] = j
    return None
```

