def lower_bound(a, x):
    '''Return the index of the first element of sorted list a that is >= x; len(a) if none.'''
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
```

```python
def caesar(s, k):
    '''Shift lowercase letters by k (mod 26), leave everything else unchanged.'''
    result = []
    for c in s:
        if 'a' <= c <= 'z':
            result.append(chr((ord(c) - ord('a') + k) % 26 + ord('a')))
        else:
            result.append(c)
    return ''.join(result)
```

